// Slack sends the payload as a URL-encoded string. We need to parse the JSON inside.
const payload = JSON.parse($json.body.payload);

const action = payload.actions[0]; // The action that triggered this event
const actionId = action.action_id;

if (actionId === "monday_button_click" || actionId === "C7\/Do"){
  throw Error("No deberia estar aca")
}

// Extract the essential data from the Slack payload
const viewId = payload.view.id;
const allBlocks = payload.view.blocks;

// --- LOGIC FOR "PIEZA A REALIZAR" DROPDOWN ---
if (actionId === "piece_type_input") {
  const selectedOptions = action.selected_options;
  const shouldShowOtherBlock = selectedOptions.some(
    (option) => option.value === "otros",
  );
  const hasOtherBlock = allBlocks.some(
    (block) => block.block_id === "piece_other_block",
  );

  if (shouldShowOtherBlock && !hasOtherBlock) {
    const otherBlock = {
      type: "input",
      block_id: "piece_other_block",
      label: { type: "plain_text", text: "Otros - Especificar" },
      element: {
        type: "plain_text_input",
        action_id: "piece_other_input",
        placeholder: {
          type: "plain_text",
          text: "Describe la pieza requerida aquí.",
        },
      },
    };
    const pieceTypeBlockIndex = allBlocks.findIndex(
      (b) => b.block_id === "piece_type_block",
    );
    allBlocks.splice(pieceTypeBlockIndex + 1, 0, otherBlock);
  } else if (!shouldShowOtherBlock && hasOtherBlock) {
    const otherBlockIndex = allBlocks.findIndex(
      (b) => b.block_id === "piece_other_block",
    );
    if (otherBlockIndex > -1) allBlocks.splice(otherBlockIndex, 1);
  }
}

// --- LOGIC FOR "FORMATO" DROPDOWN ---
if (actionId === "formats_input") {
  const selectedFormat = action.selected_option.value;
  const shouldShowDimensions = selectedFormat === "impreso";
  const hasDimensionsBlock = allBlocks.some(
    (block) => block.block_id === "dimensions_block",
  );

  if (shouldShowDimensions && !hasDimensionsBlock) {
    const dimensionsBlock = {
      type: "input",
      block_id: "dimensions_block",
      label: {
        type: "plain_text",
        text: "Dimensiones (obligatorio para impresos)",
      },
      element: {
        type: "plain_text_input",
        action_id: "dimensions_input",
        placeholder: {
          type: "plain_text",
          text: 'Ej: "A4", "8.5in x 11in", "10cm x 15cm"',
        },
      },
    };
    const formatBlockIndex = allBlocks.findIndex(
      (b) => b.block_id === "formats_block",
    );
    allBlocks.splice(formatBlockIndex + 1, 0, dimensionsBlock);
  } else if (!shouldShowDimensions && hasDimensionsBlock) {
    const dimensionsBlockIndex = allBlocks.findIndex(
      (b) => b.block_id === "dimensions_block",
    );
    if (dimensionsBlockIndex > -1) allBlocks.splice(dimensionsBlockIndex, 1);
  }
}

// Construct the final view object for the API call
const updatedView = {
  view_id: viewId,
  view: {
    type: "modal",
    callback_id: payload.view.callback_id,
    title: payload.view.title,
    submit: payload.view.submit,
    close: payload.view.close,
    blocks: allBlocks,
  },
};

// Return the JSON for the next node (the HTTP Request)
return {
  json: updatedView,
};

